<?php
namespace App\Controllers\Api;
use App\Core\{Controller,Request,Auth,Database}; use App\Models\{Product,Category,Order,Vendor};
class ApiController extends Controller { public function products(Request $r){return $this->json(['data'=>(new Product)->browse($r->input)]);} public function categories(){return $this->json(['data'=>(new Category)->all('status="active"')]);} public function vendor(Request $r,string $slug){$v=(new Vendor)->all('slug=?',[$slug])[0]??null; return $this->json(['data'=>$v]);} public function login(Request $r){ if(!Auth::attempt($r->get('email'),$r->get('password'))) return $this->json(['message'=>'Invalid credentials'],422); $token=bin2hex(random_bytes(32)); Database::pdo()->prepare('insert into api_tokens(user_id,token_hash,expires_at) values(?,?,date_add(now(), interval 30 day))')->execute([Auth::user()['id'],hash('sha256',$token)]); return $this->json(['token'=>$token,'user'=>Auth::user()]); } public function order(Request $r){ $auth=$r->headers['Authorization']??''; $user=Auth::apiUser(str_replace('Bearer ','',$auth)); if(!$user) return $this->json(['message'=>'Unauthenticated'],401); $id=(new Order)->createFromCart((int)$user['id'],$r->get('items',[]),$r->get('payment_method','cod')); return $this->json(['order_id'=>$id],201); } public function payment(Request $r,string $ref){$o=(new Order)->all('number=?',[$ref])[0]??null; return $this->json(['data'=>$o]);} }
